float det(in vec2 a, in vec2 b) { return a.x*b.y - a.y*b.x; }
float dot2(in vec2 a )          { return dot(a,a);          }

//
// Samples distance, winding and arclength of an arc defined by two points and radius.
//
// If r is positive, the circle center is on the left of the line, else on right.
//
// return a vec3(d, w, l) with:
// - d: the minimum distance from p to the circle arc
// - w: winding number at p
// - l: arc length from p0 to the nearest point on the curve at p (extends beyond the end points of the curve)
//
// Based on https://www.shadertoy.com/view/stKyzG
//
vec3 dwlArc(in vec2 p, in vec2 p0, in vec2 p1, in float r)
{
	vec2 v = p1 - p0;
	float len2 = dot2(v);
	float len = sqrt(len2);
	vec2 n = vec2(-v.y, v.x) / len;
	vec2 c = (p1 + p0) * 0.5 + sign(r) * n * sqrt(max(0., r*r - len2 * 0.25));
	mat2 rot = mat2(-n.y, n.x, n.x, n.y);
	vec2 p0t = rot * (p0 - c);

	vec2 pt = rot * (p - c);
	vec2 opt = pt;
	float rp = length(pt) - abs(r);
	pt.x = abs(pt.x);
	float dist2 = det(pt, p0t) > 0. ? dot2(pt - p0t) : rp*rp;

	// Winding
	bvec3 cond = bvec3(p.y >= p0.y, p.y < p1.y, pt.y > p0t.y);
	float inside = cond.z ? sign(rp) : 1.;
	float winding = (all(cond) || all(not(cond))) ? -inside : inside;

	// Arc length
	float halfSweep = abs(atan(p0t.x, p0t.y)); // can precalc!
	float aa = halfSweep - atan(opt.x, opt.y);
	float arclen = aa * abs(r);

	return vec3(sqrt(dist2), winding, arclen);

}

//
// Samples distance, winding and length of a line segemnt defined by two points.
//
// return a vec3(d, w, l) with:
// - d: the minimum distance from p to the line segment
// - w: winding number at p
// - l: arc length from p0 to the nearest point on the curve at p (extends beyond end points of the segment)
//
// Based on https://www.shadertoy.com/view/3tdSDj
//
vec3 dwlLine(in vec2 p, in vec2 p0, in vec2 p1)
{
	vec2 pa = p-p0, ba = p1-p0;
    float dba = dot(ba,ba);
    float t = dot(pa,ba)/dba;
	float h = clamp( t, 0.0, 1.0 );
    float d = length( pa - ba*h );

    bvec3 cond = bvec3(p.y >= p0.y, p.y < p1.y, ba.x*pa.y > ba.y*pa.x );
    float winding = (all(cond) || all(not(cond))) ? -1. : 1.;

    float len = t * sqrt(dba);

    return vec3(d, winding, len);

}

//
// Calc the length of a quadratic bezier at the start/end points and at the specified value for the parameter t.
//
// return vec2(l, ltot):
// - l: length of the bezier up to "t" 
// - ltot: total length of the curve
//
// Based on https://www.shadertoy.com/view/NltBRB
//
vec2 arcLenBezier(float t, vec2 p0, vec2 p1, vec2 p2)
{
    vec2 a1 = 2.0 * (p0 - 2.0 * p1 + p2);
    vec2 b1 = 2.0 * (p1 - p0);
    float k1 = dot(a1, a1);
    float k2 = 2.0 * dot(a1, b1);
    float k3 = dot(b1, b1);
    float k4 = 0.5f * k2 / k1;
    float k5 = k3 / k1 - k4 * k4;
    vec3 ti = vec3(0.0, t, 1.0); // calc at all three integration bounds at once
    vec3 vt = sqrt((ti + k4) * (ti + k4) + k5);
    vec3 sdft = sqrt(k1) * 0.5 * ((k4 + ti) * vt + k5 * log(abs(k4 + ti + vt)));
    return sdft.yz - sdft.x;
}

// Calculate winding using bary centric coordinates.
float windingBezier(in vec2 pos, in vec2 p0, in vec2 p1, in vec2 p2)
{
    // Calculate bary centric coordinates of the triangle.
    vec2 v0 = p1 - p0;
    vec2 v1 = p2 - p0;
    vec2 v2 = pos - p0;
    float den = det(v0, v1);
    float u = det(v2, v1) / den;
    float v = det(v0, v2) / den;
    float facing = sign(den);

    // Use the barycentric distance from edge p2-p0 to check on which side of the edge we area, the sign will flip depending how the triange winding/facing.
    bvec3 cond = bvec3(pos.y >= p0.y, pos.y < p2.y, u*facing < 0. );

    // Eval if pos is inside the bezier curve inside the triangle.
    // Using cond.z here to avoid potential gaps between the inside test and the line.
    float w = u * 0.5 + v;
    float inside = max(cond.z ? facing : -facing, sign((w * w) - v));

    return (all(cond) || all(not(cond))) ? -inside : inside;
}

//
// Samples distance, winding and length of a quad bezier curve defined by three points.
//
// return a vec3(d, w, l) with:
// - d: the minimum distance from p to the circle arc
// - w: winding number at p
// - l: arc length from p0 to the nearest point on the curve at p (extends beyond the end points of the curve)
//
// Based on https://www.shadertoy.com/view/MlKcDD
//
vec3 dwlBezier(in vec2 pos, in vec2 p0, in vec2 p1, in vec2 p2)
{
    vec2 a = p1 - p0;
    vec2 b = p0 - 2.*p1 + p2;
    vec2 c = 2.*a;
    vec2 d = p0 - pos;

    float kk = 1. / dot(b,b);
    float kx = kk * dot(a,b);
    float ky = kk * (2.*dot2(a) + dot(d,b)) / 3.;
    float kz = kk * dot(d,a);

    float p  = ky - kx*kx;
    float q  = kx * (2.*kx*kx - 3.*ky) + kz;
    float p3 = p * p * p;
    float q2 = q * q;
    float h  = q2 + 4.*p3;

    vec2 res = vec2(0.);

    if(h >= 0.) 
    {   // 1 root
        h = sqrt(h);
        vec2 x = (vec2(h, -h) - q) / 2.;
        vec2 uv = sign(x) * pow(abs(x), vec2(1. / 3.));
        float tr = uv.x + uv.y - kx;
        float t = clamp( tr, 0., 1. );
        vec2  q = d + (c + b*t) * t;

        res = vec2(dot2(q), tr);
    } else {
        // 3 roots
        float z = sqrt(-p);
        float v = acos(q / (p * z * 2.)) / 3.;
        float m = cos(v);
        float n = sin(v) * 1.732050808;

        vec2  tr =  vec2(m + m, -n - m) * z - kx;
        vec2  t = clamp(tr, 0., 1. );

        vec2  qx = d + (c + b * t.x) * t.x;
        vec2 resx = vec2(dot2(qx), tr.x);
        vec2  qy = d + (c + b * t.y) * t.y;
        vec2 resy = vec2(dot2(qy), tr.y);

        res = resx.x < resy.x ? resx : resy;
    }

    vec2 arclen = arcLenBezier(res.y, p0, p1, p2);
    float winding = windingBezier(pos, p0, p1, p2);

    return vec3(sqrt(res.x), winding, arclen.x);
}

// Dash pattern distance.
float sdDash(float d, float offset, float filled, float gap)
{
	float mfilled = filled * 0.5;
	float mgap = gap * 0.5;

	d += offset;
	float s = mod(d + (filled + gap), filled + gap);

    return (s < filled) ?
            abs(mfilled - s) - mfilled :
            mgap - abs(filled + mgap - s);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // normalized pixel coordinates
    vec2 p = (2.0*fragCoord-iResolution.xy)/iResolution.y;
    vec2 m = (2.0*iMouse.xy-iResolution.xy)/iResolution.y;

    float aa = 0.01;
    float thickness = 0.04;

    // animation
    float time = iTime;
	vec2 v0 = 0.8*cos( 0.43 *iTime + vec2(0.0,2.00) + 0.0 );
	vec2 v1 = 0.8*cos( 0.51 *iTime + vec2(0.0,1.50) + 1.0 );
	vec2 v2 = 0.8*cos( 0.64 *iTime + vec2(0.0,1.0) + 1.0 );

    // sampling
    float x = cos(0.63*iTime);
    float sw = fract(0.03*iTime);
    vec3 dsi = vec3(0.);
    if( sw < 0.4 )
        dsi = dwlArc(p, v0, v2, length(v0 - v2) * 0.5 * sign(x)*(1. + abs(x)));
    else if (sw < 0.8)
        dsi = dwlBezier(p, v0, v1, v2);
    else
        dsi = dwlLine(p, v0, v2);

    float d = dsi.x - thickness; // thick curve

    // Combine thick curve SDF with dashing 
    float dashd = sdDash(dsi.z, thickness + aa, 0.15, 0.05);
    d = max(d, dashd);

    // coloring
    vec3 col = (d>0.0) ? vec3(0.9,0.6,0.3) : vec3(0.65,0.85,1.0);
	col *= 1.0 - exp(-4.0*abs(d));
	col *= 0.8 + 0.2*cos(110.0*d);
	col = mix( col, vec3(1.0), 1.0-smoothstep(0.0,aa,abs(d)) );
    if (dsi.y < 0.)
        col = mix( col, vec3(0.0,0.5,1.), 0.5 );

    // End points
    d = max(-(length(p-v0)-0.02), length(p-v0)-0.03);
    d = min( d, length(p-v2)-0.02 );
    col = mix( col, vec3(1.,0.3,0.3), 1.0-smoothstep(0.0,aa,d) );


	fragColor = vec4(col, 1.0);
}
